/**
 * Clamp a row range to the rows of a file.
 * Returns undefined when no rows are left in the range.
 *
 * @param {number} rowStart first row of the range
 * @param {number | undefined} rowEnd end of the range (exclusive), defaults to the end of the file
 * @param {number} numRows number of rows in the file
 * @returns {[number, number] | undefined}
 */
export function clampRowRange(rowStart, rowEnd, numRows) {
  const end = Math.min(rowEnd ?? numRows, numRows)
  if (rowStart >= end) return undefined
  return [rowStart, end]
}

/**
 * Split a row range into the pieces that fall inside each row group.
 * Row groups that do not overlap the range are left out.
 *
 * @param {FileMetaData} metadata
 * @param {number} rowStart first row of the range
 * @param {number} rowEnd end of the range (exclusive)
 * @returns {[number, number][]} one [start, end) range per overlapping row group
 */
export function rowGroupSlices(metadata, rowStart, rowEnd) {
  /** @type {[number, number][]} */
  const slices = []
  let groupStart = 0
  for (const group of metadata.row_groups) {
    const groupEnd = groupStart + Number(group.num_rows)
    if (groupStart >= rowEnd) break
    if (groupEnd > rowStart) slices.push([Math.max(rowStart, groupStart), Math.min(rowEnd, groupEnd)])
    groupStart = groupEnd
  }
  return slices
}
